cypress_script:
describe('Sortable Data Tables', () => {
  it('should display sortable data tables', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('h1').should('contain', 'Data Tables');
    cy.get('#table1').should('be.visible');
    cy.get('#table2').should('be.visible');
    cy.get('#table1').find('th').should('contain', 'Last Name');
    cy.get('#table1').find('th').should('contain', 'First Name');
    cy.get('#table1').find('th').should('contain', 'Email');
    cy.get('#table1').find('th').should('contain', 'Due');
    cy.get('#table1').find('th').should('contain', 'Web Site');
    cy.get('#table1').find('th').should('contain', 'Action');
  });

  it('should not find non-existing element', () => {
    cy.visit('https://the-internet.herokuapp.com/tables');
    cy.get('#non-existing-element').should('not.exist');
  });
});

playwright_script:
test.describe('Sortable Data Tables', () => {
  test('should display sortable data tables', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    await page.locator('h1').waitFor();
    await expect(page.locator('h1')).toHaveText('Data Tables');
    await expect(page.locator('#table1')).toBeVisible();
    await expect(page.locator('#table2')).toBeVisible();
    await expect(page.locator('#table1 th')).toHaveText(['Last Name', 'First Name', 'Email', 'Due', 'Web Site', 'Action']);
  });

  test('should not find non-existing element', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
    const nonExistingElement = page.locator('#non-existing-element');
    await expect(nonExistingElement).toHaveCount(0);
  });
});
